`validators.py`:

```
"""Validators V1..V6 over depot run outputs.

Each validator subclasses ``Check`` from ``checks_base`` and implements
``check(items) -> (passed, measured)``. Callers use ``VN().run(items)``.
"""
from __future__ import annotations

from typing import Any

from checks_base import Check, is_empty

# Notification types the spec says the runs must emit at least once.
REQUIRED_NOTIFICATION_TYPES = frozenset({
    "SUPPLIER_SUSPENDED",
    "EXPIRY",
    "REORDER",
    "AUDIT_MISMATCH",
    "OVERDRAWN",
})


class V1(Check):
    """rows: every report row's value equals units * unit_cost."""

    name = "rows"

    def check(self, items: Any) -> tuple[bool, Any]:
        mismatches = []
        for row in items:
            expected = row["units"] * row["unit_cost"]
            if row["value_cents"] != expected:
                mismatches.append((row["sku"], row["wh"]))
        return (not mismatches), {"rows_checked": len(items), "mismatches": mismatches}


class V2(Check):
    """runs: every required notification type was seen across the runs."""

    name = "runs"

    def check(self, items: Any) -> tuple[bool, Any]:
        seen: set = set()
        for run in items:
            for notification in run:
                seen.add(notification[0])
        missing = REQUIRED_NOTIFICATION_TYPES - seen
        return (not missing), {"seen": sorted(seen), "missing": sorted(missing)}


class V3(Check):
    """pairs: two runs with the same seed are identical (and non-empty)."""

    name = "pairs"

    def check(self, items: Any) -> tuple[bool, Any]:
        failing_seeds = []
        compared = 0
        for pair in items:
            compared += 1
            a, b = pair["a"], pair["b"]
            # An empty output on both sides is not evidence of determinism.
            if a != b or is_empty(a):
                failing_seeds.append(pair["seed"])
        return (not failing_seeds), {"pairs_compared": compared, "failing_seeds": failing_seeds}


class V4(Check):
    """days: storage cost stayed within budget on every day."""

    name = "days"

    def check(self, items: Any) -> tuple[bool, Any]:
        over_budget = []
        for day in items:
            if day["storage_cost_cents"] > day["budget_cents"]:
                over_budget.append(day["day"])
        return (not over_budget), {"days_checked": len(items), "over_budget_days": over_budget}


class V5(Check):
    """clauses: every clause entry has at least one non-blank test."""

    name = "clauses"

    def check(self, items: Any) -> tuple[bool, Any]:
        untested = []
        for entry in items:
            tests = [t for t in (entry.get("tests") or [])
                     if isinstance(t, str) and t.strip()]
            if not tests:
                untested.append(entry["clause_id"])
        return (not untested), {"clauses_checked": len(items), "untested": untested}


class V6(Check):
    """pairs: two implementations agree on every compared pair (non-empty result)."""

    name = "pairs"

    def check(self, items: Any) -> tuple[bool, Any]:
        disagreements = []
        compared = 0
        for pair in items:
            compared += 1
            a, b = pair["a"], pair["b"]
            # Both sides returning nothing is not agreement on a result.
            if a != b or is_empty(a):
                disagreements.append(pair["key"])
        return (not disagreements), {"pairs_compared": compared, "disagreements": disagreements}
```

`checks_base.py`:

```
"""The ``Check`` base class: a check never passes on nothing (brief 3, and E2's guard condition).

``Check.run(items)`` returns ``failed: empty input`` for empty or all-unmeasured input *before*
calling the subclass, and ``failed: nothing measured`` when the subclass measured nothing. The
harness's own checks (presence, reach, parity, mutation) subclass it, and so do the agent's
validators in E2's guard condition (the agent gets this file as ``checks_base.py``).

This file is standard-library only so it can be copied verbatim into the agent's repo.
"""
from __future__ import annotations

from dataclasses import dataclass
from typing import Any


@dataclass
class CheckResult:
    passed: bool
    measured: Any
    reason: str = ""

    def __iter__(self):  # allows ``passed, measured = check.run(x)``
        yield self.passed
        yield self.measured

    def __bool__(self) -> bool:
        return bool(self.passed)


def is_empty(value: Any) -> bool:
    """True for None, empty containers, and containers whose every leaf is None or empty."""
    if value is None:
        return True
    if isinstance(value, (str, bytes)):
        return len(value) == 0
    if isinstance(value, dict):
        return len(value) == 0 or all(is_empty(v) for v in value.values())
    if isinstance(value, (list, tuple, set, frozenset)):
        return len(value) == 0 or all(is_empty(v) for v in value)
    return False


class Check:
    """Subclasses implement ``check(items) -> (passed, measured)``; callers use ``run(items)``."""

    name = "check"

    def run(self, items: Any) -> CheckResult:
        if hasattr(items, "__next__"):  # a lazy source of runs: materialise before judging emptiness
            items = list(items)
        if is_empty(items):
            return CheckResult(False, None, "failed: empty input")
        try:
            passed, measured = self.check(items)
        except Exception as exc:  # a check that crashes has not passed
            return CheckResult(False, None, f"failed: {type(exc).__name__}: {exc}")
        if is_empty(measured):
            return CheckResult(False, measured, "failed: nothing measured")
        return CheckResult(bool(passed), measured, "" if passed else "failed")

    def check(self, items: Any) -> tuple[bool, Any]:  # pragma: no cover - abstract
        raise NotImplementedError
```
